{"file_text": "@page "/settings"
@using sv_37c7f783acf44cb98e1b6f100e73e94e.Models
@using sv_37c7f783acf44cb98e1b6f100e73e94e.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool _loading = true;
    private string? _toastMessage;
    private bool _toastIsError;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = new() { "general", "announcements", "marketing", "engineering", "design" };
    private HashSet<string> _mutedChannels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _sessionToRevoke;
    private bool _showRevokeConfirm;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly List<string> _languages = new() { "English", "Spanish", "French", "German", "Japanese", "Portuguese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
        _loading = false;
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        _loading = true;
        _toastMessage = null;
        await LoadSectionData();
        _loading = false;
    }

    private async Task LoadSectionData()
    {
        switch (ActiveSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                _displayName = profile.DisplayName;
                _email = profile.Email;
                _avatarUrl = profile.AvatarUrl;
                _bio = profile.Bio;
                break;
            case "Notifications":
                var notifs = await SettingsService.GetNotificationPrefsAsync();
                _emailNotifications = notifs.EmailNotifications;
                _pushNotifications = notifs.PushNotifications;
                _weeklyDigest = notifs.WeeklyDigest;
                _mutedChannels = new HashSet<string>(notifs.MutedChannels);
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
                _changePasswordExpanded = false;
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                _theme = appearance.Theme;
                _fontSize = appearance.FontSize;
                _language = appearance.Language;
                _compactMode = appearance.CompactMode;
                break;
        }
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();
        await Task.Delay(3000);
        _toastMessage = null;
        StateHasChanged();
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _ = ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _displayName = _savedProfile.DisplayName;
            _email = _savedProfile.Email;
            _avatarUrl = _savedProfile.AvatarUrl;
            _bio = _savedProfile.Bio;
        }
    }

    // Notifications methods
    private void ToggleMutedChannel(string channel)
    {
        if (!_mutedChannels.Remove(channel))
        {
            _mutedChannels.Add(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _ = ShowToast("Notification preferences saved!");
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _ = ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _ = ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _ = ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _ = ShowToast("Session revoked.");
        }
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // Appearance methods
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _ = ShowToast("Appearance settings saved!");
    }

    // Render helpers
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>

        <div class="form-section">
            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                <p class="avatar-url">@_avatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="form-section">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(channel)"
                               @onchange="() => ToggleMutedChannel(channel)" />
                        <span class="channel-name">#@channel</span>
                        @if (_mutedChannels.Contains(channel))
                        {
                            <span class="muted-badge">Muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="form-section">
            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                        <span class="toggle-switch"></span>
                        Enable 2FA
                    </label>
                    <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                        @(_twoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings?.Sessions is not null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session.Id == "current")
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => PromptRevokeSession(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Confirm Revoke Session</h4>
                        <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </div>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h2>Appearance Settings</h2>

        <div class="form-section">
            <!-- Theme -->
            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")"
                               @onchange='() => _theme = "Light"' /> Light
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")"
                               @onchange='() => _theme = "Dark"' /> Dark
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System" checked="@(_theme == "System")"
                               @onchange='() => _theme = "System"' /> System
                    </label>
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")"
                               @onchange='() => _fontSize = "Small"' /> Small
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")"
                               @onchange='() => _fontSize = "Medium"' /> Medium
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")"
                               @onchange='() => _fontSize = "Large"' /> Large
                    </label>
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <label for="language"><strong>Language</strong></label>
                <select id="language" @bind="_language" class="form-control">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will appear with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @_theme | Font: @_fontSize | Language: @_language</p>
                    @if (_compactMode)
                    {
                        <p><em>Compact mode is enabled — reduced spacing applied.</em></p>
                    }
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}
